package corpagent.api;

import corpagent.*;
import corpagent.data.*;
import corpagent.db.*;
import corpagent.files.*;
import corpagent.llm.*;
import corpagent.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.net.*;
import java.util.*;
import java.util.zip.ZipFile;
import org.apache.poi.xslf.usermodel.*;
import org.apache.poi.xssf.usermodel.*;
import org.apache.poi.xwpf.usermodel.*;

/** Explicit opt-in integration test. Only synthetic inputs go to the configured provider. */
public final class RealFunctionalTest {
    static Path out,base;static Config config;static DataStore store;static int port;static String dbName,dbPath,projectId,projectDb;
    static List<Object> results=new ArrayList<>();static int failures;
    interface Work {void run()throws Exception;}
    static Map<String,Object> obj(Object... pairs){Map<String,Object> m=Json.newObject();for(int i=0;i<pairs.length;i+=2)m.put((String)pairs[i],pairs[i+1]);return m;}
    static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    static String xmlSignature(byte[] bytes)throws Exception{var f=javax.xml.parsers.DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);return nodeSignature(f.newDocumentBuilder().parse(new java.io.ByteArrayInputStream(bytes)).getDocumentElement());}
    static String nodeSignature(org.w3c.dom.Node n){StringBuilder s=new StringBuilder(n.getNamespaceURI()+":"+n.getLocalName());var attrs=new TreeMap<String,String>();for(int i=0;i<n.getAttributes().getLength();i++){var a=n.getAttributes().item(i);if(!"http://www.w3.org/2000/xmlns/".equals(a.getNamespaceURI()))attrs.put(a.getNamespaceURI()+":"+a.getLocalName(),a.getNodeValue());}s.append(attrs);for(int i=0;i<n.getChildNodes().getLength();i++){var child=n.getChildNodes().item(i);if(child.getNodeType()==1)s.append(nodeSignature(child));else if(child.getNodeType()==3)s.append(child.getNodeValue().trim());}return s.toString();}
    static void run(String name,Work work)throws Exception{
        String only=System.getProperty("corpagent.test.only","");if(!only.isEmpty()&&!only.equals(name))return;
        long start=System.currentTimeMillis();Map<String,Object> r=obj("scenario",name);
        try{work.run();r.put("status","PASS");System.out.println("PASS "+name);}catch(Throwable e){failures++;String detail=String.valueOf(e.getMessage()).replace(config.getApiKey(),"[key]").replace(config.getFolderId(),"[folder]");r.put("status","FAIL");r.put("error",detail);System.out.println("FAIL "+name+": "+detail.substring(0,Math.min(250,detail.length())));}
        r.put("elapsed_ms",System.currentTimeMillis()-start);results.add(r);report();
    }
    static void report()throws Exception{Files.writeString(out.resolve("real-functional-result.json"),Json.stringify(obj("status",failures==0?"PASS":"FAIL","model",config.getModel().replace(config.getFolderId(),"[folder]"),"synthetic_inputs_only",true,"tokens",TokenBudget.tokensToday(),"scenarios",results),true));}
    static String request(String method,String path,byte[] bytes)throws Exception{
        HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:"+port+path).openConnection();c.setRequestMethod(method);c.setRequestProperty("Authorization","Bearer functional-test-token");c.setReadTimeout(240000);
        if(bytes!=null){c.setDoOutput(true);try(var stream=c.getOutputStream()){stream.write(bytes);}}
        try(var stream=c.getResponseCode()<400?c.getInputStream():c.getErrorStream()){return new String(stream.readAllBytes(),StandardCharsets.UTF_8);}finally{c.disconnect();}
    }
    static Map<String,Object> api(String method,String path,Map<String,Object> body)throws Exception{
        Map<String,Object> response=Json.parseObject(request(method,path,body==null?null:Json.stringify(body).getBytes(StandardCharsets.UTF_8)));
        check(response!=null&&Json.bool(response,"ok",false),"API "+path+": "+Json.str(response,"error","invalid response"));return Json.asMap(response.get("data"));
    }
    static Map<String,Object> chat(String id,String text,Map<String,Object> extra)throws Exception{
        Map<String,Object> body=obj("chat_id",id,"message",text);if(extra!=null)body.putAll(extra);Map<String,Object> r=api("POST","/api/chat",body);
        String response=Json.str(r,"response","");Files.writeString(out.resolve(id+"-response.txt"),response);check(!response.isBlank()&&!response.startsWith("❌")&&!response.startsWith("⛔"),response.isBlank()?"empty model response":response);return r;
    }
    static String response(Map<String,Object> result){return Json.str(result,"response","");}
    static void verifyDownload(Path file)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:"+port+"/api/files/download?name="+URLEncoder.encode(file.getFileName().toString(),StandardCharsets.UTF_8)).openConnection();c.setRequestProperty("Authorization","Bearer functional-test-token");try(var stream=c.getInputStream()){check(Arrays.equals(stream.readAllBytes(),Files.readAllBytes(file)),"download differs from generated artifact");}finally{c.disconnect();}}
    static long number(String sql)throws Exception{try(var c=SqliteHelper.open(dbPath);var s=c.createStatement();var r=s.executeQuery(sql)){check(r.next(),"no query result");return r.getLong(1);}}
    static Map<String,Object> upload(String chat,String name,byte[] bytes)throws Exception{
        api("POST","/api/chats",obj("chat_id",chat,"title","Synthetic functional test"));
        Map<String,Object> result=Json.parseObject(request("POST","/api/files/upload?chat_id="+chat+"&name="+URLEncoder.encode(name,StandardCharsets.UTF_8),bytes));
        check(Json.bool(result,"ok",false),"upload failed");return Json.asMap(Json.arr(Json.asMap(result.get("data")),"files").get(0));
    }
    static Map<String,Object> dbContext(boolean confirm){return obj("databases",List.of(dbName),"confirm_writes",confirm);}
    static String tool(String fragment){for(String name:store.getTools().keySet())if(name.toLowerCase().contains(fragment))return name;throw new AssertionError("tool not found: "+fragment);}
    public static void main(String[] args)throws Exception{
        check(args.length>=2,"Usage: RealFunctionalTest <config-path> <output-dir> [--probe]");
        config=Config.fromRaw(new LinkedHashMap<>(Json.parseObject(Files.readString(Paths.get(args[0]),StandardCharsets.UTF_8))));
        check(config.getProvider().equals("yandex")&&new URI(config.getBaseUrl()).getHost().equals("ai.api.cloud.yandex.net"),"real tests require the official configured Yandex endpoint");
        check(!config.getApiKey().isBlank()&&!config.getFolderId().isBlank(),"configured credentials required");
        config.setTemperature(0.1);config.setMaxTokens(Math.max(config.getMaxTokens(),3000));out=Paths.get(args[1]).toAbsolutePath();Files.createDirectories(out);base=out.resolve("data");Files.createDirectories(base);
        if(Arrays.asList(args).contains("--probe")){List<String> models=new DeepSeekClient(config).listModels();Files.writeString(out.resolve("model-catalog.json"),Json.stringify(obj("count",models.size(),"models",models.stream().map(x->x.replace(config.getFolderId(),"[folder]")).toList()),true));System.out.println("REAL model catalog: "+models.size()+" models");return;}
        if(Arrays.asList(args).contains("--stream-usage")){run("completed_stream_token_accounting",()->{long before=TokenBudget.tokensToday();String text=new DeepSeekClient(config).callStreaming(List.of(obj("role","user","content","Ответь одним словом: SYNTHETIC_USAGE_OK")),"",new DeepSeekClient.StreamHandler(){public void onToken(String s){}public void onDone(String s){}public void onError(String s){throw new AssertionError(s);}});Files.writeString(out.resolve("stream-response.txt"),text);check(!text.isBlank()&&!text.startsWith("\u274c"),"unexpected stream response: "+text);check(TokenBudget.tokensToday()>before,"completed stream usage missing");});if(failures>0)System.exit(1);return;}
        store=new DataStore(base.toString());DatabaseManager db=new DatabaseManager(base.resolve("databases").toString(),base.resolve("backups").toString(),store);FileCreator creator=new FileCreator(base.resolve("output").toString(),System.getProperty("user.dir"));Agent agent=new Agent(config,store,db,creator);Settings settings=new Settings(base.toString());
        ApiServer server=new ApiServer(Auth.withToken("functional-test-token"),new StaticHandler("web"));new ChatRoutes(agent,store,settings).register(server);new FilesRoutes(base.toString(),store).register(server);new NotesRoutes(store).register(server);new ProjectsRoutes(store,db).register(server);new DatabasesRoutes(store,db).register(server);new CatalogRoutes(store).register(server);new SettingsRoutes(config,settings,new DeepSeekLlmTester()).register(server);port=server.start(new int[]{0});
        if(Arrays.asList(args).contains("--presentation-only")){dbName="presentation_source";check(db.createDatabase(dbName,"CREATE TABLE audit_items(id INTEGER PRIMARY KEY,name TEXT,amount INTEGER); INSERT INTO audit_items VALUES(1,'Alpha',19); INSERT INTO audit_items VALUES(2,'Beta',23); INSERT INTO audit_items VALUES(3,'Gamma',31);","Synthetic presentation fixture").success,"presentation fixture");dbPath=Json.str(store.getDatabase(dbName),"path","");System.setProperty("corpagent.test.only","presentation_in_corporate_template");}
        try{
            if(Arrays.asList(args).contains("--matrix")){ScenarioMatrixTest.runMatrix(agent,creator,db);report();if(failures>0)throw new AssertionError("Scenario matrix contains failed checks");return;}
            run("model_catalog",()->{List<String> models=new DeepSeekClient(config).listModels();check(models.size()>2,"catalog still limited");Files.writeString(out.resolve("model-catalog.json"),Json.stringify(obj("count",models.size(),"models",models.stream().map(x->x.replace(config.getFolderId(),"[folder]")).toList()),true));});
            run("document_intent_with_database",()->{check(IntentRouter.detect("Создай презентацию по данным БД")==IntentRouter.Intent.PRESENTATION,"presentation misrouted");check(IntentRouter.detect("Создай Excel паспорт из базы данных")==IntentRouter.Intent.EXCEL,"Excel misrouted");});
            run("database_from_description",()->{chat("description-db","Создай базу данных audit_description с одной таблицей audit_description(id INTEGER PRIMARY KEY, title TEXT).",null);Map<String,Object> info=store.getDatabase("audit_description");check(info!=null&&SqliteHelper.getTables(Json.str(info,"path","")).contains("audit_description"),"description produced SQL instead of a database");});
            run("plain_chat_and_skill",()->{store.getSkills().put("Synthetic exact reply",obj("enabled",true,"code","When the user writes CODE_REQUEST, respond with exactly SYNTHETIC_SKILL_OK"));Map<String,Object> r=chat("plain","CODE_REQUEST",obj("skills",List.of("Synthetic exact reply")));check(response(r).contains("SYNTHETIC_SKILL_OK"),"skill instruction not applied");});
            run("streaming_chat",()->{String s=request("POST","/api/chat/stream",Json.stringify(obj("chat_id","stream","message","Ответь одним словом: SYNTHETIC_STREAM_OK")).getBytes(StandardCharsets.UTF_8));Files.writeString(out.resolve("stream-response.txt"),s);String answer="";for(String frame:s.split("\n\n"))if(frame.contains("event: done")){Map<String,Object> done=Json.parseObject(frame.substring(frame.indexOf("data: ")+6).trim());answer=Json.str(done,"text","");}check(answer.contains("SYNTHETIC_STREAM_OK")&&!answer.startsWith("❌"),"assistant stream response missing");});
            run("create_database_from_uploaded_csv",()->{
                String csv="id,name,amount\n1,Alpha,17\n2,Beta,23\n3,Gamma,31\n";Map<String,Object> file=upload("create-db","synthetic-items.csv",csv.getBytes(StandardCharsets.UTF_8));check(Json.str(file,"text","").contains("Gamma"),"CSV extraction failed");Set<String> before=new HashSet<>(store.getDatabases().keySet());
                chat("create-db","Создай базу данных из загруженного CSV. Имя таблицы строго audit_items, поля id INTEGER PRIMARY KEY, name TEXT, amount INTEGER. Сохрани все три строки без изменений.",obj("attachment_ids",List.of(Json.str(file,"id",""))));
                List<String> added=store.getDatabases().keySet().stream().filter(x->!before.contains(x)).toList();check(added.size()==1,"database not registered");dbName=added.get(0);dbPath=Json.str(store.getDatabase(dbName),"path","");check(Files.isRegularFile(Paths.get(dbPath)),"database file missing");check(number("SELECT COUNT(*) FROM audit_items")==3&&number("SELECT SUM(amount) FROM audit_items")==71,"rows or amounts differ from source");
            });
            run("question_database_exact_sum",()->{check(dbName!=null,"requires database");Map<String,Object> r=chat("question","Сколько составляет сумма amount в таблице audit_items в БД? Обязательно выполни SELECT SUM(amount) AS total FROM audit_items через db_query. Ответь числом.",dbContext(false));check(response(r).contains("71"),"incorrect database answer");check(Json.arr(r,"usage").toString().contains(dbName),"db_query was not executed");});
            run("database_write_requires_confirmation",()->{check(dbName!=null,"requires database");chat("write-denied","Измени данные в БД: выполни UPDATE audit_items SET amount=19 WHERE id=1 через db_execute. Если запись запрещена, сообщи об этом.",dbContext(false));check(number("SELECT amount FROM audit_items WHERE id=1")==17,"write happened without confirmation");});
            run("confirmed_database_write",()->{check(dbName!=null,"requires database");chat("write-approved","Измени данные в БД: выполни ровно UPDATE audit_items SET amount=19 WHERE id=1 через db_execute. Запись подтверждена. После записи прочитай значение через db_query.",dbContext(true));check(number("SELECT amount FROM audit_items WHERE id=1")==19,"confirmed write not executed");});
            run("updated_database_answer",()->{check(dbName!=null,"requires database");Map<String,Object> r=chat("updated-question","Проверь БД через db_query: SELECT SUM(amount) AS total FROM audit_items. Ответь числом.",dbContext(false));check(response(r).contains("73"),"answer ignores updated database");});
            run("presentation_in_corporate_template",()->{
                Map<String,Object> extra=dbContext(false);extra.put("tools",List.of(tool("шаблоне")));Map<String,Object> r=chat("presentation","Создай презентацию в корпоративном шаблоне: 5 слайдов о синтетическом проекте REAL_SYNTHETIC_PRESENTATION. Используй данные audit_items из выбранной БД, получи фактическую сумму amount. На титуле обязательно REAL_SYNTHETIC_PRESENTATION.",extra);
                Path file=Paths.get(Json.str(r,"file_path",""));check(Files.isRegularFile(file),"PPTX not generated");try(var ppt=new XMLSlideShow(Files.newInputStream(file))){check(ppt.getSlides().size()>=5,"too few slides");check(!ppt.getSlideMasters().isEmpty(),"template master absent");}check(FileExtractor.extractText(file.toFile()).contains("REAL_SYNTHETIC_PRESENTATION")&&FileExtractor.extractText(file.toFile()).contains("73"),"presentation content or actual aggregate lost");
                verifyDownload(file);
                try(var template=new ZipFile(creator.getCorporatePresentationTemplate());var generated=new ZipFile(file.toFile())){String entry="ppt/theme/theme1.xml";check(xmlSignature(template.getInputStream(template.getEntry(entry)).readAllBytes()).equals(xmlSignature(generated.getInputStream(generated.getEntry(entry)).readAllBytes())),"corporate theme differs");}
            });
            run("excel_in_passport_template",()->{Map<String,Object> r=chat("excel","Создай Excel паспорт синтетического проекта. Данные строго: Name;Value\nREAL_SYNTHETIC_EXCEL;42",obj("tools",List.of(tool("паспорта"))));Path file=Paths.get(Json.str(r,"file_path",""));check(Files.isRegularFile(file),"XLSX not generated");try(var workbook=new XSSFWorkbook(Files.newInputStream(file))){check(workbook.getNumberOfSheets()>0,"workbook empty");}String text=FileExtractor.extractText(file.toFile());check(text.contains("REAL_SYNTHETIC_EXCEL")&&text.contains("42"),"generated Excel lost source data");});
            run("excel_risk_register_template",()->{Map<String,Object> r=chat("risk-excel","Создай Excel реестр рисков. Данные строго: Risk;Impact\nREAL_SYNTHETIC_RISK;high",obj("tools",List.of(tool("реестра"))));Path file=Paths.get(Json.str(r,"file_path",""));check(Files.isRegularFile(file)&&FileExtractor.extractText(file.toFile()).contains("REAL_SYNTHETIC_RISK"),"risk register missing data");try(var generated=new XSSFWorkbook(Files.newInputStream(file));var template=new XSSFWorkbook(Files.newInputStream(Paths.get(creator.getCorporateExcelTemplate("риск"))))){check(generated.getNumCellStyles()>=template.getNumCellStyles(),"Excel template styles lost");}});
            run("status_presentation_tool",()->{Map<String,Object> r=chat("status-ppt","Создай презентацию статуса синтетического проекта REAL_STATUS_PRESENTATION, пять слайдов: цель, сделано, план, риски, решения.",obj("tools",List.of(tool("статуса"))));Path file=Paths.get(Json.str(r,"file_path",""));check(Files.isRegularFile(file)&&FileExtractor.extractText(file.toFile()).contains("REAL_STATUS_PRESENTATION"),"status PPT tool failed");});
            run("project_with_seven_chats",()->{Map<String,Object> r=api("POST","/api/projects",obj("name","Synthetic real test project","db_name","real_project","description","Synthetic data only"));projectId=Json.str(r,"project_id","");if(projectId.isEmpty())projectId=store.getProjects().keySet().iterator().next();Map<String,Object> project=store.getProject(projectId);projectDb=Json.str(project,"db","");check(store.getChats().values().stream().filter(x->projectId.equals(Json.str(Json.asMap(x),"project",""))).count()==7,"project did not create seven chats");});
            run("meeting_protocol_persisted",()->{check(projectDb!=null&&!projectDb.isEmpty(),"requires project database");chat("protocol","Разбери протокол встречи и запиши в БД через db_execute: синтетическая встреча REAL_SYNTHETIC_MEETING, дата 2026-11-11, участники Иван Тестов и Анна Примерова. Решение: одобрить пилот. Поручение Ивану: подготовить стенд до 2026-11-20. Перед записью изучи реальную схему через db_query. Запиши встречу, решение и задачу, не создавай новых таблиц. Изменения подтверждены.",obj("databases",List.of(projectDb),"confirm_writes",true));String path=Json.str(store.getDatabase(projectDb),"path","");check(!SqliteHelper.getTableRows(path,"meetings",100).isEmpty(),"meeting not persisted");check(!SqliteHelper.getTableRows(path,"meeting_decisions",100).isEmpty(),"decision not persisted");check(!SqliteHelper.getTableRows(path,"tasks",100).isEmpty(),"task not persisted");});
            run("project_status_from_database",()->{Map<String,Object> r=chat("status","Сформируй статус проекта по БД: что сделано, что осталось, фокус. Используй db_query для чтения tasks, не придумывай задачи.",obj("databases",List.of(projectDb)));check(response(r).contains("стенд"),"status lost recorded task");});
            for(String ext:List.of("txt","md","csv","html","docx","pdf","xlsx","pptx"))run("attachment_"+ext,()->{
                String marker="SYNTHETIC_"+ext.toUpperCase()+"_8147",id="attachment-"+ext;byte[] bytes;
                if(ext.equals("docx")){try(var doc=new XWPFDocument();var output=new java.io.ByteArrayOutputStream()){doc.createParagraph().createRun().setText(marker);doc.write(output);bytes=output.toByteArray();}}
                else if(ext.equals("xlsx")){try(var workbook=new XSSFWorkbook();var output=new java.io.ByteArrayOutputStream()){workbook.createSheet().createRow(0).createCell(0).setCellValue(marker);workbook.write(output);bytes=output.toByteArray();}}
                else if(ext.equals("pptx")){String file=creator.createPptx(marker+"\nSynthetic attachment",null);bytes=Files.readAllBytes(Paths.get(file));}
                else if(ext.equals("pdf")){try(var doc=new org.apache.pdfbox.pdmodel.PDDocument();var output=new java.io.ByteArrayOutputStream()){var page=new org.apache.pdfbox.pdmodel.PDPage();doc.addPage(page);try(var content=new org.apache.pdfbox.pdmodel.PDPageContentStream(doc,page)){content.beginText();content.setFont(org.apache.pdfbox.pdmodel.font.PDType1Font.HELVETICA,12);content.newLineAtOffset(60,700);content.showText(marker);content.endText();}doc.save(output);bytes=output.toByteArray();}}
                else bytes=marker.getBytes(StandardCharsets.UTF_8);
                Map<String,Object> file=upload(id,"synthetic."+ext,bytes);check(Json.str(file,"text","").contains(marker),"attachment extraction failed");Map<String,Object> r=chat(id,"Прочитай приложенный файл. Верни точную строку, начинающуюся SYNTHETIC_, без изменений.",obj("attachment_ids",List.of(Json.str(file,"id",""))));check(response(r).contains(marker),"model did not receive extracted attachment");
            });
            run("real_model_http_tool",()->{var mock=com.sun.net.httpserver.HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);mock.createContext("/",x->{byte[] b="SYNTHETIC_HTTP_TOOL_OK".getBytes(StandardCharsets.UTF_8);x.sendResponseHeaders(200,b.length);try(var stream=x.getResponseBody()){stream.write(b);}});mock.start();try{store.getTools().put("synthetic_http_lookup",obj("name","synthetic_http_lookup","type","http","enabled",true,"description","Return a synthetic verification code","endpoint","http://127.0.0.1:"+mock.getAddress().getPort()+"/","method","GET"));Map<String,Object> r=chat("http-tool","Вызови инструмент synthetic_http_lookup и верни полученный код без изменений.",obj("tools",List.of("synthetic_http_lookup")));check(response(r).contains("SYNTHETIC_HTTP_TOOL_OK")&&Json.arr(r,"usage").toString().contains("synthetic_http_lookup"),"HTTP tool was not actually executed");}finally{mock.stop(0);}});
            for(String type:List.of("python","shell"))run("real_model_"+type+"_tool",()->{String marker="SYNTHETIC_"+type.toUpperCase()+"_TOOL_OK",name="synthetic_"+type+"_echo";store.getTools().put(name,obj("name",name,"type",type,"enabled",true,"description","Return a synthetic verification code","endpoint",type.equals("python")?"print('"+marker+"')":"cmd.exe /c echo "+marker));Map<String,Object> r=chat(type+"-tool","Вызови инструмент "+name+" и верни код из результата без изменений.",obj("tools",List.of(name)));check(response(r).contains(marker)&&Json.arr(r,"usage").toString().contains(name),"tool not actually executed");});
            run("custom_sql_tool_respects_confirmation",()->{store.getTools().put("synthetic_sql_write",obj("name","synthetic_sql_write","type","sql","enabled",true,"description","Change one synthetic amount","endpoint","UPDATE audit_items SET amount=999 WHERE id=1"));Map<String,Object> extra=dbContext(false);extra.put("tools",List.of("synthetic_sql_write"));chat("sql-tool-denied","Вызови инструмент synthetic_sql_write. Если операция запрещена, сообщи об этом.",extra);check(number("SELECT amount FROM audit_items WHERE id=1")==19,"custom SQL tool bypassed confirmation");});
            run("notes_and_history_persistence",()->{api("POST","/api/notes",obj("title","Synthetic generated note","text","REAL_SYNTHETIC_NOTE"));store.saveAll();DataStore reopened=new DataStore(base.toString());check(!reopened.getChats().isEmpty()&&!reopened.getNotes().isEmpty(),"saved data not recovered");});
            report();System.out.println("REAL_TEST_RESULT="+out.resolve("real-functional-result.json"));
        }finally{server.stop();}
        if(failures>0)System.exit(1);
    }
}
